        VALUES ('acme.never_registered', 7, 'scope', 'payments.charge');
        RAISE EXCEPTION 'CHECK 51 FAILED: scopes were declared for a version nobody registered';
    EXCEPTION
        WHEN foreign_key_violation THEN NULL;
