BEGIN
    BEGIN
        INSERT INTO plt01.cat_products
            (tenant_id, product_key, product_type, created_by, correlation_id)
        VALUES ('11111111-1111-4111-8111-111111111111', 'smuggled', 'service',
                '33333333-3333-4333-8333-333333333333',
                '33333333-3333-4333-8333-333333333333');
