        'LBANK', 'bank', 'Bank', 'JOD', '33333333-3333-4333-8333-333333333333',
        '33333333-3333-4333-8333-333333333333'),
       ('11111111-1111-4111-8111-111111111111', 'ffffffff-7000-4000-8000-00000000000d',
